# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">PERİYODİK ÖZELLİKLERİN DEĞİŞİM YÖNLERİ VE NEDENSEL İLİŞKİSİ</text>\n  <rect x="20" y="45" width="320" height="195" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="180" y="66" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e40af">SOLDAN SAĞA (AYNI PERİYOTTA: 1A → 8A)</text>\n  <text x="35" y="92" font-size="11" font-weight="bold" fill="#1e3a8a">• Katman (enerji düzeyi) sayısı SABİT kalır.</text>\n  <text x="35" y="114" font-size="11" font-weight="bold" fill="#1e3a8a">• Çekirdek yükü (proton sayısı) ve çekim gücü ARTAR.</text>\n  <text x="35" y="138" font-size="11" font-weight="bold" fill="#b91c1c">• Atom Yarıçapı (Hacmi): AZALIR (Kardan adamın burnu).</text>\n  <text x="35" y="162" font-size="11" font-weight="bold" fill="#15803d">• 1. İyonlaşma Enerjisi: GENELLİKLE ARTAR</text>\n  <text x="45" y="178" font-size="10.5" fill="#166534">Sıralama: 1A &lt; 3A &lt; 2A &lt; 4A &lt; 6A &lt; 5A &lt; 7A &lt; 8A</text>\n  <text x="35" y="200" font-size="11" font-weight="bold" fill="#15803d">• Elektronegatiflik: ARTAR (7A\'da en yüksek; 8A hariç).</text>\n  <text x="35" y="222" font-size="10.5" fill="#1e40af">• Metalik özellik azalır, ametalik özellik artar.</text>\n  <rect x="360" y="45" width="320" height="195" rx="10" fill="#fffbeb" stroke="#d97706" stroke-width="2"/>\n  <text x="520" y="66" text-anchor="middle" font-size="12" font-weight="bold" fill="#b45309">YUKARIDAN AŞAĞIYA (AYNI GRUPTA)</text>\n  <text x="375" y="92" font-size="11" font-weight="bold" fill="#78350f">• Katman (temel enerji düzeyi) sayısı ARTAR.</text>\n  <text x="375" y="114" font-size="11" font-weight="bold" fill="#78350f">• Değerlik elektronları çekirdekten uzaklaşır.</text>\n  <text x="375" y="138" font-size="11" font-weight="bold" fill="#15803d">• Atom Yarıçapı (Hacmi): ARTAR (Kardan adam gövdesi).</text>\n  <text x="375" y="162" font-size="11" font-weight="bold" fill="#b91c1c">• 1. İyonlaşma Enerjisi: KESİNLİKLE AZALIR.</text>\n  <text x="375" y="186" font-size="11" font-weight="bold" fill="#b91c1c">• Elektronegatiflik: AZALIR (En yüksek: Flor = 4,0).</text>\n  <text x="375" y="210" font-size="10.5" fill="#92400e">• Katyon (X+) oluşurken yarıçap küçülür; Anyon (Y-)</text>\n  <text x="383" y="226" font-size="10.5" fill="#92400e">oluşurken elektron başına çekim azaldığı için yarıçap büyür.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">İYONLAŞMA ENERJİSİ GRAFİĞİ VE ARDIŞIK SIÇRAMA YORUMU</text>\n  <rect x="20" y="45" width="330" height="195" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="185" y="66" text-anchor="middle" font-size="12" font-weight="bold" fill="#15803d">PERİYOTTA 1. İE GRAFİĞİ (3 AŞAĞI 5 YUKARI)</text>\n  <polyline points="45,205 75,160 105,180 135,145 165,110 195,130 225,95 255,68 285,215" fill="none" stroke="#16a34a" stroke-width="2.5"/>\n  <circle cx="45" cy="205" r="4" fill="#15803d"/><text x="42" y="222" font-size="9.5" font-weight="bold">1A</text>\n  <circle cx="75" cy="160" r="4" fill="#dc2626"/><text x="70" y="152" font-size="9.5" font-weight="bold" fill="#b91c1c">2A</text>\n  <circle cx="105" cy="180" r="4" fill="#15803d"/><text x="100" y="196" font-size="9.5" font-weight="bold">3A</text>\n  <circle cx="135" cy="145" r="4" fill="#15803d"/><text x="130" y="138" font-size="9.5" font-weight="bold">4A</text>\n  <circle cx="165" cy="110" r="4" fill="#dc2626"/><text x="160" y="102" font-size="9.5" font-weight="bold" fill="#b91c1c">5A</text>\n  <circle cx="195" cy="130" r="4" fill="#15803d"/><text x="190" y="146" font-size="9.5" font-weight="bold">6A</text>\n  <circle cx="225" cy="95" r="4" fill="#15803d"/><text x="220" y="88" font-size="9.5" font-weight="bold">7A</text>\n  <circle cx="255" cy="68" r="4" fill="#1d4ed8"/><text x="250" y="60" font-size="9.5" font-weight="bold" fill="#1d4ed8">8A</text>\n  <circle cx="285" cy="215" r="4" fill="#dc2626"/><text x="280" y="232" font-size="9.5" font-weight="bold" fill="#b91c1c">1A(alt)</text>\n  <text x="35" y="235" font-size="9.5" fill="#14532d">Küresel simetri: 2A &gt; 3A ve 5A &gt; 6A</text>\n  <rect x="365" y="45" width="315" height="195" rx="10" fill="#faf5ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="522" y="66" text-anchor="middle" font-size="12" font-weight="bold" fill="#7e22ce">ARDIŞIK İYONLAŞMA ENERJİSİ TABLOSU</text>\n  <text x="380" y="92" font-size="10.5" fill="#581c87">• İE değerleri arasında en az 3,5 - 4 katlık ani artış</text>\n  <text x="388" y="108" font-size="10.5" fill="#581c87">soygaz düzenine geçildiğini gösterir ve grup numarasını verir.</text>\n  <text x="380" y="134" font-size="10.5" font-weight="bold" fill="#6b21a8">Örnek (A grubu elementleri için kJ/mol):</text>\n  <text x="380" y="154" font-size="10.5" fill="#581c87">• X: İE1=496, İE2=4560 (9,2 kat artış!) → 1A grubu</text>\n  <text x="380" y="174" font-size="10.5" fill="#581c87">• Y: İE1=738, İE2=1450, İE3=7730 (5,3 kat!) → 2A grubu</text>\n  <text x="380" y="194" font-size="10.5" fill="#581c87">• Z: İE1=578, İE2=1817, İE3=2745, İE4=11577 → 3A grubu</text>\n  <text x="380" y="218" font-size="10.5" font-weight="bold" fill="#b91c1c">• Kural: Her zaman İE_n &gt; ... &gt; İE3 &gt; İE2 &gt; İE1 olur!</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">KİMYASAL TÜRLER VE ETKİLEŞİMLERİN SINIFLANDIRILMASI</text>\n  <rect x="20" y="45" width="320" height="195" rx="10" fill="#ecfeff" stroke="#0891b2" stroke-width="2"/>\n  <text x="180" y="68" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#0e7490">1. KİMYASAL TÜRLER (ATOM, İYON, MOLEKÜL)</text>\n  <text x="35" y="96" font-size="11" font-weight="bold" fill="#155e75">• Atom (Nötr tek tanecik):</text>\n  <text x="45" y="112" font-size="10.5" fill="#0e7490">He, Ne, Ar, Fe, Cu, Na, Au (Metaller ve soygazlar)</text>\n  <text x="35" y="136" font-size="11" font-weight="bold" fill="#155e75">• Molekül (Kovalent bağlı nötr atom grubu):</text>\n  <text x="45" y="152" font-size="10.5" fill="#0e7490">- Element molekülü: H2, O2, N2, Cl2, O3, P4, S8</text>\n  <text x="45" y="168" font-size="10.5" fill="#0e7490">- Bileşik molekülü: H2O, CO2, NH3, CH4, HCl, C6H12O6</text>\n  <text x="35" y="192" font-size="11" font-weight="bold" fill="#155e75">• İyon (Yüklü tanecik — Katyon [+] ve Anyon [-]):</text>\n  <text x="45" y="208" font-size="10.5" fill="#0e7490">Na+, Mg2+, NH4+ (Katyon) | Cl-, O2-, SO4^2-, NO3- (Anyon)</text>\n  <text x="35" y="226" font-size="10" font-weight="bold" fill="#b91c1c">Not: NaCl gibi iyonik bileşikler molekül DEĞİLDİR (birim hücre)!</text>\n  <rect x="360" y="45" width="320" height="195" rx="10" fill="#fff1f2" stroke="#e11d48" stroke-width="2"/>\n  <text x="520" y="68" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#9f1239">2. GÜÇLÜ VE ZAYIF ETKİLEŞİMLER (40 kJ/mol SINIRI)</text>\n  <text x="375" y="96" font-size="11" font-weight="bold" fill="#881337">• Güçlü Etkileşimler (Kimyasal Bağlar — &gt; 40 kJ/mol):</text>\n  <text x="385" y="114" font-size="10.5" fill="#9f1239">1) İyonik Bağ (Metal + Ametal iyonları arası: NaCl, MgO)</text>\n  <text x="385" y="132" font-size="10.5" fill="#9f1239">2) Kovalent Bağ (Ametal + Ametal elektron ortaklığı: H2O)</text>\n  <text x="385" y="150" font-size="10.5" fill="#9f1239">3) Metalik Bağ (Metal katyonu + Elektron denizi: Fe, Cu)</text>\n  <text x="375" y="176" font-size="11" font-weight="bold" fill="#1e40af">• Zayıf Etkileşimler (Fiziksel Bağlar — &lt; 40 kJ/mol):</text>\n  <text x="385" y="194" font-size="10.5" fill="#1e3a8a">1) Van der Waals Kuvvetleri (Dipol-dipol, İyon-dipol, London)</text>\n  <text x="385" y="212" font-size="10.5" fill="#1e3a8a">2) Hidrojen Bağı (H atomunun F, O, N ile yaptığı etkileşim)</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
